//! Embeds what `src/DIME.rc` and the linker gave the C++ `DIMESettings.exe`:
//! the icons (`IDI_*`, `IDI_DIMESETTINGS` first), the version resource
//! (`IDR_VERSION`, numbers from `src/BuildInfo.h`) and the manifest (the
//! linker's default `asInvoker` plus Common Controls 6). The resources are
//! written as a `.res` file here, without `rc.exe`, and handed to the
//! linker, which converts `.res` inputs itself.
//!
//! `src/BuildInfo.h` is regenerated by `src/BuildInfo.cmd` (the MSBuild
//! projects run it before building); a plain `cargo build` uses the file as
//! it is. The executable also gets `DIME_BUILD_VER_MAJOR`,
//! `DIME_BUILD_VER_MINOR` and `DIME_BUILD_COMMIT_COUNT` for the caption.
//!
//! Two fixes over the C++ executable's version resource, which was the
//! DLL's: `FILETYPE` is `VFT_APP`, and `InternalName` / `OriginalFilename`
//! are `DIMESettings.exe`. The DLL's string tables are left out (the
//! settings app never loads them).

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

/// `(IDI_*, file under src/image)`, in `DIME.rc` order.
const ICONS: &[(u16, &str)] = &[
    (10, "DIMESettings.ico"),
    (11, "TSFDayi.ico"),
    (12, "TSFArray.ico"),
    (13, "TSFPhonetic.ico"),
    (14, "TSFGeneric.ico"),
    (21, "ImeModeOn.ico"),
    (22, "ImeModeOff.ico"),
    (24, "DoubleSingleByteOn.ico"),
    (25, "DoubleSingleByteOff.ico"),
];

const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;
const RT_VERSION: u16 = 16;
const RT_MANIFEST: u16 = 24;
const LANG_NEUTRAL: u16 = 0;
const LANG_EN_US: u16 = 0x0409;

const MANIFEST: &str = r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
  <trustInfo xmlns="urn:schemas-microsoft-com:asm.v3">
    <security>
      <requestedPrivileges>
        <requestedExecutionLevel level="asInvoker" uiAccess="false"></requestedExecutionLevel>
      </requestedPrivileges>
    </security>
  </trustInfo>
  <dependency>
    <dependentAssembly>
      <assemblyIdentity type="win32" name="Microsoft.Windows.Common-Controls" version="6.0.0.0" processorArchitecture="*" publicKeyToken="6595b64144ccf1df" language="*"></assemblyIdentity>
    </dependentAssembly>
  </dependency>
</assembly>
"#;

fn main() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let src = manifest_dir.join("../../../src");
    let build_info = src.join("BuildInfo.h");
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={}", build_info.display());

    let info = read_build_info(&build_info);
    let get = |k: &str| info.get(k).cloned().unwrap_or_else(|| "0".to_string());
    let major: u32 = get("BUILD_VER_MAJOR").parse().unwrap_or(0);
    let minor: u32 = get("BUILD_VER_MINOR").parse().unwrap_or(0);
    let count: u32 = get("BUILD_COMMIT_COUNT").parse().unwrap_or(0);
    let date1: u32 = get("BUILD_DATE_1").parse().unwrap_or(0);
    let version_str = get("BUILD_VERSION_STR").trim_matches('"').to_string();
    println!("cargo:rustc-env=DIME_BUILD_VER_MAJOR={major}");
    println!("cargo:rustc-env=DIME_BUILD_VER_MINOR={minor}");
    println!("cargo:rustc-env=DIME_BUILD_COMMIT_COUNT={count}");

    let windows_msvc = env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows")
        && env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    if !windows_msvc {
        return;
    }

    let mut res = ResFile::new();
    let mut next_image = 1u16;
    for &(id, file) in ICONS {
        let path = src.join("image").join(file);
        println!("cargo:rerun-if-changed={}", path.display());
        let bytes = fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        add_icon(&mut res, id, &bytes, &mut next_image);
    }
    let debug = env::var("PROFILE").as_deref() == Ok("debug");
    let version = version_info([major, minor, count, date1], &version_str, debug);
    res.add(RT_VERSION, 1, LANG_NEUTRAL, 0x0030, &version);
    res.add(RT_MANIFEST, 1, LANG_EN_US, 0x0030, MANIFEST.as_bytes());

    let out = PathBuf::from(env::var("OUT_DIR").unwrap()).join("DIMESettings.res");
    fs::write(&out, &res.bytes).unwrap();
    println!("cargo:rustc-link-arg-bins={}", out.display());
}

/// `#define NAME VALUE` lines of `BuildInfo.h`.
fn read_build_info(path: &Path) -> HashMap<String, String> {
    let text = fs::read_to_string(path).unwrap_or_default();
    text.lines()
        .filter_map(|l| {
            let mut parts = l.trim().splitn(3, char::is_whitespace);
            if parts.next()? != "#define" {
                return None;
            }
            let name = parts.next()?.to_string();
            let value = parts.next().unwrap_or("").trim().to_string();
            Some((name, value))
        })
        .collect()
}

/// A `.res` file: the empty leading entry, then one entry per resource.
struct ResFile {
    bytes: Vec<u8>,
}

impl ResFile {
    fn new() -> Self {
        let mut r = ResFile { bytes: Vec::new() };
        r.entry(0, 0, 0, 0, &[]);
        r
    }

    fn add(&mut self, ty: u16, name: u16, lang: u16, flags: u16, data: &[u8]) {
        self.entry(ty, name, lang, flags, data);
    }

    /// `RESOURCEHEADER` with ordinal type and name (32 bytes), then the data
    /// padded to a DWORD.
    fn entry(&mut self, ty: u16, name: u16, lang: u16, flags: u16, data: &[u8]) {
        let b = &mut self.bytes;
        put32(b, data.len() as u32);
        put32(b, 32);
        put16(b, 0xFFFF);
        put16(b, ty);
        put16(b, 0xFFFF);
        put16(b, name);
        put32(b, 0); // DataVersion
        put16(b, flags);
        put16(b, lang);
        put32(b, 0); // Version
        put32(b, 0); // Characteristics
        b.extend_from_slice(data);
        pad4(b);
    }
}

/// One `.ico` as `RT_ICON` images (numbered from `next_image`, as `rc`
/// does) and the `RT_GROUP_ICON` `id` that lists them.
fn add_icon(res: &mut ResFile, id: u16, ico: &[u8], next_image: &mut u16) {
    let count = u16::from_le_bytes([ico[4], ico[5]]) as usize;
    let mut group = Vec::new();
    put16(&mut group, 0);
    put16(&mut group, 1);
    put16(&mut group, count as u16);
    for i in 0..count {
        let e = &ico[6 + i * 16..6 + (i + 1) * 16];
        let size = u32::from_le_bytes([e[8], e[9], e[10], e[11]]) as usize;
        let offset = u32::from_le_bytes([e[12], e[13], e[14], e[15]]) as usize;
        let image_id = *next_image;
        *next_image += 1;
        res.add(RT_ICON, image_id, LANG_NEUTRAL, 0x1010, &ico[offset..offset + size]);
        // GRPICONDIRENTRY: the ICONDIRENTRY's first 12 bytes, then the id.
        group.extend_from_slice(&e[..12]);
        put16(&mut group, image_id);
    }
    res.add(RT_GROUP_ICON, id, LANG_NEUTRAL, 0x1030, &group);
}

/// A `VS_VERSIONINFO` block: `wLength`, `wValueLength`, `wType`, the key,
/// the value and the children, each part DWORD aligned.
fn node(key: &str, value: &[u8], value_len: u16, text: bool, children: &[Vec<u8>]) -> Vec<u8> {
    let mut b = vec![0, 0];
    put16(&mut b, value_len);
    put16(&mut b, u16::from(text));
    for c in key.encode_utf16().chain(std::iter::once(0)) {
        put16(&mut b, c);
    }
    pad4(&mut b);
    b.extend_from_slice(value);
    for child in children {
        pad4(&mut b);
        b.extend_from_slice(child);
    }
    let len = b.len() as u16;
    b[0..2].copy_from_slice(&len.to_le_bytes());
    b
}

fn string_entry(key: &str, value: &str) -> Vec<u8> {
    let mut v = Vec::new();
    let units: Vec<u16> = value.encode_utf16().chain(std::iter::once(0)).collect();
    for &c in &units {
        put16(&mut v, c);
    }
    node(key, &v, units.len() as u16, true, &[])
}

fn version_info(v: [u32; 4], version_str: &str, debug: bool) -> Vec<u8> {
    const COPYRIGHT: &str = "Copyright 2026 Jeremy Wu";
    let ms = (v[0] << 16) | (v[1] & 0xFFFF);
    let ls = ((v[2] & 0xFFFF) << 16) | (v[3] & 0xFFFF);
    let mut fixed = Vec::new();
    for d in [
        0xFEEF_04BD, // dwSignature
        0x0001_0000, // dwStrucVersion
        ms,
        ls,
        ms,
        ls,
        0x3F,               // FILEFLAGSMASK
        u32::from(debug),   // FILEFLAGS (VS_FF_DEBUG)
        0x0004_0004,        // FILEOS: VOS_NT_WINDOWS32
        1,                  // FILETYPE: VFT_APP
        0,
        0,
        0,
    ] {
        put32(&mut fixed, d);
    }
    let strings = [
        ("CompanyName", "Jeremy Wu"),
        ("FileDescription", "Dumb Input Method Editor (DIME)"),
        ("FileVersion", version_str),
        ("InternalName", "DIMESettings.exe"),
        ("LegalCopyright", COPYRIGHT),
        ("LegalsearchTextright", COPYRIGHT),
        ("OriginalFilename", "DIMESettings.exe"),
        ("ProductName", "DIME"),
        ("ProductVersion", version_str),
    ];
    let table: Vec<Vec<u8>> = strings.iter().map(|(k, s)| string_entry(k, s)).collect();
    let string_table = node("040904b0", &[], 0, true, &table);
    let string_info = node("StringFileInfo", &[], 0, true, &[string_table]);
    let mut translation = Vec::new();
    put16(&mut translation, 0x0409);
    put16(&mut translation, 1200);
    put16(&mut translation, 0x0404);
    put16(&mut translation, 1200);
    let var = node("Translation", &translation, translation.len() as u16, false, &[]);
    let var_info = node("VarFileInfo", &[], 0, true, &[var]);
    node("VS_VERSION_INFO", &fixed, fixed.len() as u16, false, &[string_info, var_info])
}

fn put16(b: &mut Vec<u8>, v: u16) {
    b.extend_from_slice(&v.to_le_bytes());
}

fn put32(b: &mut Vec<u8>, v: u32) {
    b.extend_from_slice(&v.to_le_bytes());
}

fn pad4(b: &mut Vec<u8>) {
    while !b.len().is_multiple_of(4) {
        b.push(0);
    }
}
